import{_ as t,o as a,c as e,ae as o}from"./chunks/framework.Dzr56EFm.js";const m=JSON.parse('{"title":"设计趋势 - 2026-08-08","description":"","frontmatter":{"date":"2026-08-08T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-08-uxtrend.md","filePath":"daily/2026-08-08-uxtrend.md"}'),n={name:"daily/2026-08-08-uxtrend.md"};function s(i,r,g,p,h,l){return a(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-08-08" tabindex="-1">设计趋势 - 2026-08-08 <a class="header-anchor" href="#设计趋势-2026-08-08" aria-label="Permalink to &quot;设计趋势 - 2026-08-08&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于AI与用户体验的融合。最值得关注的是面向代理的用户体验设计，探讨了如何将AI代理融入数字设备体验设计中，实现人机无缝交互。此外，Figma社区提供的AI工作流程，通过图像、视频和创意生成，推动创意项目从概念到实现的效率。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探讨了设计新型数字设备用户体验的代理UX设计原则。</p><p><strong>能解决什么问题</strong>: 解决传统UX原则无法完全适应AI驱动代理系统的独特挑战。</p><p><strong>产品应用</strong>: 可应用于实际产品，通过人本原则指导开发，提升用户体验。</p><p><strong>示例场景</strong>: 智能助手协助用户进行日常任务规划和情绪调节。</p><hr><h3 id="_2-ai驱动的工作流程是什么" tabindex="-1">2. AI驱动的工作流程是什么？ <a class="header-anchor" href="#_2-ai驱动的工作流程是什么" aria-label="Permalink to &quot;2. AI驱动的工作流程是什么？&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxtbe.medium.com/ai-workflows-its-not-about-going-faster-it-s-about-thinking-differently-0972defead9c" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI工作流程是将AI逻辑融入项目决策、任务和周期中。</p><p><strong>能解决什么问题</strong>: 如何将AI融入设计流程而不牺牲用户体验。</p><p><strong>产品应用</strong>: 可以应用到数字产品设计中，通过AI辅助设计决策和任务执行。</p><p><strong>示例场景</strong>: 设计师提出需求，AI生成信息架构和视觉变体。</p><hr><h3 id="_3-ai辅助工作流开发的最佳实践" tabindex="-1">3. AI辅助工作流开发的最佳实践 <a class="header-anchor" href="#_3-ai辅助工作流开发的最佳实践" aria-label="Permalink to &quot;3. AI辅助工作流开发的最佳实践&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@sai.kancherla/best-practices-for-ai-assisted-workflow-development-29096fa94d7b" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 遵循最佳实践以确保AI辅助工作流的效率和可靠性。</p><p><strong>能解决什么问题</strong>: 解决开发复杂工作流时的效率和准确性问题。</p><p><strong>产品应用</strong>: 适用于需要AI辅助开发复杂工作流的实际产品，如自动化系统。</p><p><strong>示例场景</strong>: 自动化文件上传、数据提取和验证流程。</p><hr><h3 id="_4-人工智能时代下的用户体验2-0-代理体验设计" tabindex="-1">4. 人工智能时代下的用户体验2.0：代理体验设计 <a class="header-anchor" href="#_4-人工智能时代下的用户体验2-0-代理体验设计" aria-label="Permalink to &quot;4. 人工智能时代下的用户体验2.0：代理体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 用户体验设计需适应人工智能代理，实现人机无缝交互。</p><p><strong>能解决什么问题</strong>: 解决非人类用户（如AI代理）的用户体验设计问题。</p><p><strong>产品应用</strong>: 适用于需要AI代理与人类协作的产品，如自动化客服系统。</p><p><strong>示例场景</strong>: AI代理自动预约医生，提升预约效率和准确性。</p><hr><h3 id="_5-figma中的ai工作流程-图像、视频与创意生成" tabindex="-1">5. Figma中的AI工作流程：图像、视频与创意生成 <a class="header-anchor" href="#_5-figma中的ai工作流程-图像、视频与创意生成" aria-label="Permalink to &quot;5. Figma中的AI工作流程：图像、视频与创意生成&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/community/ai-workflows" target="_blank" rel="noreferrer">AI Workflows for Image, Video &amp; Creative Generation | Figma</a></p><p><strong>一句话摘要</strong>: Figma社区提供的AI工作流程，助力创意项目从想法到输出。</p><p><strong>能解决什么问题</strong>: 解决AI工具生成内容时一致性和效率问题。</p><p><strong>产品应用</strong>: 适用于创意项目，通过定制工作流程提升设计效率。</p><p><strong>示例场景</strong>: 为营销活动生成产品图像和视觉故事。</p><hr><h3 id="_6-figma-2026设计师现状-ai提升设计质量" tabindex="-1">6. Figma 2026设计师现状：AI提升设计质量 <a class="header-anchor" href="#_6-figma-2026设计师现状-ai提升设计质量" aria-label="Permalink to &quot;6. Figma 2026设计师现状：AI提升设计质量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI在设计领域提升质量与速度，设计师转向策略与情感判断。</p><p><strong>能解决什么问题</strong>: 解决设计过程中的效率和质量平衡问题。</p><p><strong>产品应用</strong>: 适用于产品设计，通过AI辅助提高设计效率和质量。</p><p><strong>示例场景</strong>: 设计师使用AI工具快速生成原型，然后进行细节优化。</p><hr><h3 id="_7-2026年ai原生产品的8种用户体验模式" tabindex="-1">7. 2026年AI原生产品的8种用户体验模式 <a class="header-anchor" href="#_7-2026年ai原生产品的8种用户体验模式" aria-label="Permalink to &quot;7. 2026年AI原生产品的8种用户体验模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/8-ux-patterns-for-ai-native-workflows-in-2026-c469c35d7513" target="_blank" rel="noreferrer">8 UX Patterns for AI-Native Products in 2026</a></p><p><strong>一句话摘要</strong>: AI没有消灭UX，而是将设计价值转移到了AI工作流程中。</p><p><strong>能解决什么问题</strong>: AI技术的发展使得用户体验设计的重点从界面转向了围绕AI的规则和信任。</p><p><strong>产品应用</strong>: 可以应用到产品中，通过AI优化工作流程和上下文感知界面。</p><p><strong>示例场景</strong>: 智能助手根据用户行为自动调整推荐内容。</p><hr><h3 id="_8-ai时代下的用户体验设计革新" tabindex="-1">8. AI时代下的用户体验设计革新 <a class="header-anchor" href="#_8-ai时代下的用户体验设计革新" aria-label="Permalink to &quot;8. AI时代下的用户体验设计革新&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@c.montante_42326/what-deepl-agent-means-for-project-managers-in-ux-design-integrating-ai-for-inclusive-language-3bf40973a2ec" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: DeepL Agent为UX设计带来多语种支持和自动化工作流程。</p><p><strong>能解决什么问题</strong>: 解决多语言环境下的用户体验设计和自动化任务问题。</p><p><strong>产品应用</strong>: 适用于需要多语种支持和自动化流程的全球性产品。</p><p><strong>示例场景</strong>: 设计一个支持30多种语言的政府服务门户。</p><hr><h3 id="_9-使用cursor-ai快速构建react网页应用" tabindex="-1">9. 使用Cursor AI快速构建React网页应用 <a class="header-anchor" href="#_9-使用cursor-ai快速构建react网页应用" aria-label="Permalink to &quot;9. 使用Cursor AI快速构建React网页应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ux-planet/vibe-coding-for-web-with-cursor-ai-0059aa5e5803" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Cursor AI可以帮助快速可视化构建网页应用并收集反馈。</p><p><strong>能解决什么问题</strong>: 解决非专业开发者快速构建网页应用的需求。</p><p><strong>产品应用</strong>: 可应用于初步设计阶段，但需迭代优化以满足实际需求。</p><p><strong>示例场景</strong>: 使用Cursor AI快速搭建一个基本的React网页应用。</p><hr><h3 id="_10-ai代理工作流设计模式概览" tabindex="-1">10. AI代理工作流设计模式概览 <a class="header-anchor" href="#_10-ai代理工作流设计模式概览" aria-label="Permalink to &quot;10. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类规划和执行任务。</p><p><strong>产品应用</strong>: 可应用于构建智能代理，提高任务处理的灵活性和效率。</p><p><strong>示例场景</strong>: 智能客服系统通过工作流模式处理客户咨询。</p><hr>',75)])])}const c=t(n,[["render",s]]);export{m as __pageData,c as default};
